1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUMS: Record<string, number> = {
4	  sword: 100,
5	};
6	
7	const COMPONENT_BASE_PREMIUM = 25;
8	const COMPONENT_BLOCK_SIZE = 3;
9	const COMPONENT_BLOCK_PREMIUM = 60;
10	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
11	
12	const FIRST_INSURANCE_SURCHARGE = 0.1;
13	const CURSE_SURCHARGE = 0.5;
14	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
15	const HIGH_ENCHANTMENT_THRESHOLD = 5;
16	
17	interface Item {
18	  type: string;
19	  cursed?: boolean;
20	  enchantment?: number;
21	}
22	
23	interface QuoteStep {
24	  op: "quote";
25	  items: Item[];
26	}
27	
28	interface Scenario {
29	  customer: { yearsWithMHPCO: number };
30	  steps: QuoteStep[];
31	}
32	
33	interface QuoteResult {
34	  premium: number;
35	}
36	
37	interface ScenarioResult {
38	  results: QuoteResult[];
39	}
40	
41	const componentGroupBase = (count: number): number =>
42	  count === COMPONENT_BLOCK_SIZE
43	    ? COMPONENT_BLOCK_PREMIUM
44	    : count * COMPONENT_BASE_PREMIUM;
45	
46	const countByType = (items: Item[]): Map<string, number> => {
47	  const counts = new Map<string, number>();
48	  for (const item of items) {
49	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
50	  }
51	  return counts;
52	};
53	
54	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
55	
56	interface PricedUnit {
57	  base: number;
58	  surcharges: number[];
59	}
60	
61	const mainItemUnit = (item: Item): PricedUnit => {
62	  const base = BASE_PREMIUMS[item.type];
63	  const surcharges: number[] = [];
64	  if (item.cursed) surcharges.push(base * CURSE_SURCHARGE);
65	  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD) {
66	    surcharges.push(base * HIGH_ENCHANTMENT_SURCHARGE);
67	  }
68	  return { base, surcharges };
69	};
70	
71	const componentUnit = (count: number): PricedUnit => ({
72	  base: componentGroupBase(count),
73	  surcharges: [],
74	});
75	
76	const pricedUnits = (items: Item[]): PricedUnit[] => {
77	  const mainUnits = items.filter((item) => !isComponent(item)).map(mainItemUnit);
78	
79	  const components = items.filter(isComponent);
80	  const componentUnits = [...countByType(components).values()].map(componentUnit);
81	
82	  return [...mainUnits, ...componentUnits];
83	};
84	
85	const unitTotal = (unit: PricedUnit): number =>
86	  unit.base +
87	  unit.base * FIRST_INSURANCE_SURCHARGE +
88	  unit.surcharges.reduce((sum, surcharge) => sum + surcharge, 0);
89	
90	const quotePremium = (items: Item[]): number => {
91	  const itemsTotal = pricedUnits(items).reduce(
92	    (sum, unit) => sum + unitTotal(unit),
93	    0,
94	  );
95	  return Math.ceil(itemsTotal + PROCESSING_FEE);
96	};
97	
98	export const runScenario = (scenario: Scenario): ScenarioResult => {
99	  const results = scenario.steps.map((step) => ({
100	    premium: quotePremium(step.items),
101	  }));
102	  return { results };
103	};
